import re

TITLE = re.compile(r"^\s*(?P<title>Work with System Status)\s+(?P<system>\S+)\s*$")
STAMP = re.compile(r"^\s*(?P<date>\d\d/\d\d/\d\d)\s+(?P<time>\d\d:\d\d:\d\d)(?:\s+(?P<zone>\S+))?\s*$")
PAIR = re.compile(r"(?P<field>\S(?:.*?\S)?)\s*(?:\. )*\.?\s*:(?:\s+(?P<value>\S+(?: \S+)*))?")
POOL_HEADER = re.compile(r"^\s*(?:System\s+Pool\s+Reserved\s+Max|Pool\s+Size \(M\)\s+Size \(M\))")
POOL = re.compile(r"^\s*(?P<pool>\d+)\s+(?P<vals>[\d.+]+(?:\s+[\d.+]+)*)\s*$")
SKIP = re.compile(r"^\s*(?:Type changes \(if allowed\), press Enter\.|Bottom|More\.\.\.|Command|===>|F\d+=)")
POOL_COLS = ["Pool Size (M)", "Reserved Size (M)", "Max Active", "DB Fault", "DB Pages", "Non-DB Fault",
             "Non-DB Pages", "Act-Wait", "Wait-Inel", "Act-Inel"]


def parse(lines):
    screen = {"name": "screen", "kind": "kv", "lines": [], "records": [{}]}
    status = {"name": "status", "kind": "kv", "lines": [], "records": [{}]}
    pools = {"name": "pools", "kind": "table", "lines": [], "records": []}
    skip, groups = [], {}
    for i, ln in enumerate(lines):
        if not ln.strip():
            continue
        if SKIP.match(ln):
            skip.append(i)
            continue
        m = TITLE.match(ln)
        if m:
            screen["records"][0].update({"Screen": m.group("title"), "System": m.group("system")})
            screen["lines"].append(i)
            continue
        m = STAMP.match(ln)
        if m:
            screen["records"][0].update({"Date": m.group("date"), "Time": m.group("time"),
                                         "Zone": m.group("zone") or ""})
            screen["lines"].append(i)
            continue
        if POOL_HEADER.match(ln):
            pools["lines"].append(i)
            continue
        m = POOL.match(ln)
        if m:
            vals = m.group("vals").split()
            rec = {"System Pool": m.group("pool")}
            for k, v in zip(POOL_COLS, vals + [""] * (len(POOL_COLS) - len(vals))):
                rec[k] = v
            pools["records"].append(rec)
            pools["lines"].append(i)
            continue
        pairs = list(PAIR.finditer(ln))
        if pairs:
            for side, p in enumerate(pairs):
                field, value = p.group("field"), p.group("value") or ""
                if not value and side == len(pairs) - 1:
                    groups[side] = field
                    continue
                if side in groups:
                    field = groups[side] + ": " + field
                status["records"][0][field] = value
            status["lines"].append(i)
    return {"blocks": [screen, status, pools], "skip": skip}
